import { createDescentRenderer } from './descent-renderer.js';
import { DT,descentStep,replayDescent } from './descent.js';
import { descentInitial,deltaV } from './engine.js';
export function mountDescent({flight,host,onSave,onFinish}){
  let controls=(flight.manualControls||[]).map(c=>[...c]),s=replayDescent(descentInitial(flight),controls),paused=true,throttle=.45,steer=0,raf=0,last=0,acc=0,done=false,outcomeTime=0,previousState=s;
  const reduced=window.matchMedia('(prefers-reduced-motion: reduce)');
  host.innerHTML=`<section class="descent-station"><div class="section-title"><div><span class="label">FINAL 180 METRES / MANUAL CONTROL</span><h2>Bring it down gently.</h2></div><button class="button secondary" id="descent-pause">Start descent</button></div><p>Land within ±35 m of the beacon, below 3 m/s vertically and 2 m/s sideways. Tilt redirects thrust; too much tilt reduces vertical braking. Up/down changes throttle; left/right steers. P pauses.</p><canvas id="descent-canvas" width="1000" height="500" role="img" aria-label="Live lunar descent, with altitude and velocity reported below"></canvas><div class="descent-readouts" aria-live="off"></div><div class="descent-controls"><label>Throttle <output id="throttle-value">45%</output><input id="descent-throttle" type="range" min="0" max="100" value="45"></label><label>Horizontal thrust <select id="descent-steer"><option value="0">Vertical</option><option value="-1">Left</option><option value="1">Right</option></select></label></div><p id="descent-status" role="status">Paused. Set your controls, then start. Progress saves every second; leaving this screen pauses the attempt.</p><p class="tiny muted">Local 2D dynamics · 1.62 m/s² gravity · fixed 0.1 s integration · no atmosphere. This is a fictional flat landing zone, not a terrain map. The approach burn has already been allocated; final descent uses actual thrust and fuel.</p></section>`;
  const q=sel=>host.querySelector(sel),canvas=q('canvas'),pause=q('#descent-pause'),range=q('#descent-throttle'),select=q('#descent-steer');
  const cinema=document.querySelector('#flight-cinema'),viewport=document.createElement('div');viewport.className='manual-viewport';viewport.innerHTML='<div class="descent-view-heading"><div><span class="label">SURFACE APPROACH</span><h2>Final descent</h2></div><div class="descent-views" role="group" aria-label="Descent camera"><button type="button" data-descent-view="chase" aria-pressed="true">Chase</button><button type="button" data-descent-view="approach" aria-pressed="false">Approach</button></div></div><div class="descent-stage"><span class="descent-target" aria-hidden="true"></span><span class="descent-scene-note">ILLUSTRATIVE TERRAIN · LIVE FLIGHT STATE</span></div>';cinema.style.display='none';cinema.before(viewport);viewport.querySelector('.descent-stage').prepend(canvas);const visual=createDescentRenderer(canvas,{design:flight.design,marker:viewport.querySelector('.descent-target')});viewport.querySelector('.descent-target').hidden=canvas.dataset.renderer!=='3d';viewport.querySelectorAll('[data-descent-view]').forEach(button=>{button.disabled=canvas.dataset.renderer!=='3d';button.onclick=()=>{visual.setView?.(button.dataset.descentView);viewport.querySelectorAll('[data-descent-view]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));};});const status=document.createElement('p');status.className='descent-main-status';status.setAttribute('aria-live','polite');status.textContent='PAUSED · Set throttle and steering, then start descent.';viewport.append(status);
  function draw(dt=0){
    const alpha=paused||done?1:Math.max(0,Math.min(1,acc/DT));const displayed={...s,x:previousState.x+(s.x-previousState.x)*alpha,y:previousState.y+(s.y-previousState.y)*alpha};
    visual.draw(displayed,{throttle,steer,paused,dt,time:s.time+acc,motion:!reduced.matches,impactProgress:done&&s.status==='impact'?Math.min(1,outcomeTime/3.5):null});
    if(done){q('#descent-status').textContent=s.reason;status.textContent=(paused?'PAUSED · ':'IMPACT · ')+({contact:'Contact flash',breakup:'Spacecraft breakup',ejecta:'Debris falling to the surface',settled:'Wreckage settled'}[canvas.dataset.impactPhase]||s.reason);}
    const bar=document.querySelector('.telemetry .meter-track i');if(bar)bar.style.width=`${s.fuel/flight.design.fuel*100}%`;const telemetry=document.querySelectorAll('.telemetry .telemetry-readout strong');if(telemetry[0])telemetry[0].innerHTML=`${s.fuel.toFixed(1)}<span>kg</span>`;if(telemetry[1])telemetry[1].innerHTML=`${Math.round(deltaV(s.dry+s.fuel,s.dry,s.isp))}<span>m/s</span>`;
    q('.descent-readouts').innerHTML=`<span>ALTITUDE <strong>${s.y.toFixed(1)} m</strong></span><span>VERTICAL <strong>${s.vy.toFixed(1)} m/s</strong></span><span>SIDEWAYS <strong>${s.vx.toFixed(1)} m/s</strong></span><span>OFFSET <strong>${s.x.toFixed(1)} m</strong></span><span>FUEL <strong>${s.fuel.toFixed(1)} kg</strong></span>`;
  }
  function persist(){flight.manualControls=controls.map(c=>[...c]);onSave();}
  function toggle(){paused=!paused;pause.textContent=done?(paused?'Resume impact replay':'Pause impact replay'):(paused?'Resume descent':'Pause descent');q('#descent-status').textContent=paused?'Paused. Your attempt is saved.':'Descent active. Keep your vertical and sideways speed under control.';status.textContent=paused?'PAUSED · Your attempt is saved.':'DESCENT ACTIVE · Brake early. Watch both velocities.';if(paused)persist();draw();}
  pause.onclick=toggle;range.oninput=()=>{throttle=Number(range.value)/100;q('#throttle-value').textContent=`${range.value}%`;draw();};select.onchange=()=>{steer=Number(select.value);draw();};
  function key(e){if(done&&!['p','P'].includes(e.key))return;if(document.querySelector('dialog[open]')||e.target.matches('input,select,textarea'))return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','p','P'].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();if(e.key.toLowerCase()==='p'){if(!e.repeat)toggle();return;}if(e.key==='ArrowUp'||e.key==='ArrowDown'){throttle=Math.max(0,Math.min(1,throttle+(e.key==='ArrowUp'?.05:-.05)));range.value=Math.round(throttle*100);q('#throttle-value').textContent=`${range.value}%`;}else{steer=e.key==='ArrowLeft'?-1:1;select.value=String(steer);}}}
  function release(e){if(e.key==='ArrowLeft'||e.key==='ArrowRight'){steer=0;select.value='0';}}
  function visibility(){if(document.hidden&&!paused)toggle();}
  document.addEventListener('keydown',key,true);document.addEventListener('keyup',release);document.addEventListener('visibilitychange',visibility);
  function tick(now){const dt=Math.min(.1,(now-last)/1000||0);last=now;if(done){if(!paused&&!document.hidden)outcomeTime+=dt;draw(dt);if(outcomeTime>=3.5){onFinish({id:'manual-arrival',controls},{visualized:true});return;}raf=requestAnimationFrame(tick);return;}if(!paused&&!document.hidden){acc+=dt;while(acc>=DT&&s.status==='flying'){acc-=DT;const c=[throttle,steer];controls.push(c);previousState=s;s=descentStep(s,c);if(controls.length%10===0)persist();}draw(dt);if(s.status!=='flying'){done=true;q('#descent-status').textContent=s.reason;status.textContent=s.reason;host.querySelectorAll('input,select').forEach(el=>el.disabled=true);persist();if(s.status==='impact'&&!reduced.matches&&canvas.dataset.renderer==='3d'){paused=false;viewport.querySelector('h2').textContent='Surface impact';host.querySelector('h2').textContent='Impact confirmed';pause.textContent='Pause impact replay';const skip=document.createElement('button');skip.className='button secondary';skip.textContent='View flight result';skip.onclick=()=>{outcomeTime=3.5;paused=false;};host.querySelector('.descent-station').append(skip);draw();}else{paused=true;draw();onFinish({id:'manual-arrival',controls});return;}}}raf=requestAnimationFrame(tick);}
  viewport.scrollIntoView({block:'start',behavior:'instant'});draw();raf=requestAnimationFrame(tick);pause.focus({preventScroll:true});
  return ()=>{cinema.style.display='';viewport.remove();visual.dispose();cancelAnimationFrame(raf);document.removeEventListener('keydown',key,true);document.removeEventListener('keyup',release);document.removeEventListener('visibilitychange',visibility);if(!done)persist();};
}
